  if (!file.is_open()) {
    if (error) {
      *error = "Failed to open file " + path.string();
    }
    return false;
  }

  content->assign(std::istreambuf_iterator<char>(file), std::istreambuf_iterator<char>());
  if (!file.good() && !file.eof()) {
